js/technical-demo.js.before:
/* Page-anchored corner trigger scrolls away with the header: it cannot
   cover later instructions/actions. Expanded data stays in document flow. */
html[data-demo-presentation=speech] #top-bar{padding-right:60px!important}
#qs-technical-demo[data-module=speech]{position:static}
#qs-technical-demo[data-module=speech]:has(>button[aria-expanded=false]){display:contents;margin:0;padding:0;border:0;background:none}
#qs-technical-demo[data-module=speech]>button{position:absolute;top:max(12px,env(safe-area-inset-top));right:max(12px,env(safe-area-inset-right));width:48px;height:48px;padding:0;font-size:0;text-align:center;z-index:95}
#qs-technical-demo[data-module=speech]>button:focus-visible{outline:3px solid var(--tech)!important;outline-offset:3px}
#qs-technical-demo[data-module=speech]>button::after{content:'+';font-size:1.5rem;line-height:1}
#qs-technical-demo[data-module=speech]>button[aria-expanded=true]::after{content:'−'}
#qs-technical-demo[data-module=speech] #mobile-dbg-panel{position:static!important;inset:auto!important;max-height:40svh!important;max-width:100%;box-sizing:border-box;overflow:auto}

js/technical-demo.js.after:
/* Existing Speech controls stay at the bottom-right of the data panel,
   in document flow: no fixed layer can cover testing or keyboard UI. */
#qs-technical-demo[data-module=speech] .qs-speech-controls{display:flex;flex-wrap:wrap;justify-content:flex-end;align-items:start;gap:8px;margin-top:8px;padding-right:env(safe-area-inset-right);padding-bottom:env(safe-area-inset-bottom)}
#qs-technical-demo[data-module=speech] .qs-speech-controls #debug-toggle,
#qs-technical-demo[data-module=speech] .qs-speech-controls #dev-log-tools{position:static!important;inset:auto!important;transform:none!important;margin:0!important;width:auto!important;max-width:100%!important;flex:0 1 auto}
#qs-technical-demo[data-module=speech] .qs-speech-controls #debug-toggle,
#qs-technical-demo[data-module=speech] .qs-speech-controls #dev-copy-log{min-width:48px;min-height:48px!important;width:auto!important;max-width:100%;padding:10px!important;font-size:.875rem!important;white-space:normal;overflow-wrap:anywhere}
#test-screen.done #qs-technical-demo[data-module=speech] #debug-toggle{display:block!important}
#qs-technical-demo[data-module=speech] #debug-box[style*="display: block"]{display:block!important}
#qs-technical-demo[data-module=speech] #debug-box,
#qs-technical-demo[data-module=speech] #mobile-dbg-panel{position:static!important;inset:auto!important;width:100%!important;margin:8px 0 0!important;max-height:40svh!important;max-width:100%;box-sizing:border-box;overflow:auto;overflow-wrap:anywhere}

const controls=document.createElement('div');controls.className='qs-speech-controls';root.append(controls);
const collectSpeech=()=>{
  for(const id of ['debug-toggle','dev-log-tools','debug-box']){
    const element=document.getElementById(id),parent=id==='debug-box'?root:controls;
    if(element&&!parent.contains(element)){movedControls.push({button:element,parent:element.parentNode,next:element.nextSibling});parent.append(element);}
  }
